"""Supplementary Rasa docs-search tool.

Exposes ``search_rasa_documentation``, a function tool that retrieves Rasa
documentation passages for a query.
"""

from typing import List, Optional

import structlog
from agents import function_tool
from pydantic import BaseModel, Field

from rasa.builder import config
from rasa.builder.copilot.agent_sdk.tools.constants import (
    TOOL_SEARCH_RASA_DOCUMENTATION,
)
from rasa.builder.document_retrieval.base import BaseRetriever, RetrievalStatus
from rasa.builder.document_retrieval.local.config import (
    EmbedConfig,
    LocalRetrievalConfig,
)
from rasa.builder.document_retrieval.local.retrieval import (
    LocalDocumentRetrieval,
)
from rasa.builder.telemetry.langfuse_integration.langfuse_compat import observe

structlogger = structlog.get_logger()


class DocumentSearchDocument(BaseModel):
    """A single retrieved documentation passage with provenance."""

    index: int
    title: str
    url: str
    content: str


class DocumentSearchToolResponse(BaseModel):
    """Structured response for the ``search_rasa_documentation`` tool."""

    documents: List[DocumentSearchDocument] = Field(default_factory=list)
    error: Optional[str] = None


# Read-only, built once and reused for the whole service session.
# Warmed at server startup (see main.py) so the first user request does not pay
# the index-load cost.
_retriever: Optional[BaseRetriever] = None


def _build_retriever() -> BaseRetriever:
    """Construct the local backend by ingesting the prebuilt parquet vectors.

    Pull-and-serve: the vectors are built off the serving path (CI) and ingested
    directly here — no corpus load and no embedding at deploy time.
    """
    if not config.LOCAL_VECTORS_PARQUET_PATH:
        raise ValueError(
            "Local document retrieval requires LOCAL_VECTORS_PARQUET_PATH "
            "(a prebuilt parquet vector artifact) to be set."
        )

    local_config = LocalRetrievalConfig(
        index_cache_dir=config.LOCAL_INDEX_CACHE_DIR or ".retrieval_index",
        embedder=EmbedConfig(embed_cache_dir=config.LOCAL_EMBED_CACHE_DIR),
        vectors_artifact_path=config.LOCAL_VECTORS_PARQUET_PATH,
    )
    return LocalDocumentRetrieval(local_config)


def get_retriever() -> BaseRetriever:
    """Return the singleton retriever, building it lazily on first use."""
    global _retriever
    if _retriever is None:
        _retriever = _build_retriever()
        structlogger.info(
            "agent_sdk.tools.document_search.retriever_initialized",
            backend=type(_retriever).__name__,
        )
    return _retriever


@function_tool(name_override=TOOL_SEARCH_RASA_DOCUMENTATION)
@observe(
    name=f"document_search_tool.{TOOL_SEARCH_RASA_DOCUMENTATION}",
    as_type="generation",
)
async def search_rasa_documentation(query: str) -> DocumentSearchToolResponse:
    """Search Rasa documentation for relevant information.

    Args:
        query: The search query to find relevant documentation.

    Returns:
        DocumentSearchToolResponse with structured results (index, title, url,
        content). Returns an empty list with ``error`` set on failure — never
        raises.
    """
    try:
        response = await get_retriever().retrieve(query)

        if response.status is RetrievalStatus.ERROR:
            structlogger.error(
                "agent_sdk.tools.document_search.error",
                event_info="Retrieval backend reported an error",
                query=query,
                error=response.error,
            )
            return DocumentSearchToolResponse(error=response.error)

        documents: List[DocumentSearchDocument] = []
        for idx, result in enumerate(response.results, start=1):
            if not result.url:
                structlogger.warning(
                    "agent_sdk.tools.document_search.missing_url",
                    event_info="Retrieved result has no URL; skipping",
                )
                continue
            documents.append(
                DocumentSearchDocument(
                    index=idx,
                    title=result.title or "Untitled",
                    url=result.url,
                    content=result.content,
                )
            )

        return DocumentSearchToolResponse(documents=documents)

    except Exception as e:
        structlogger.error(
            "agent_sdk.tools.document_search.error",
            event_info="Doc-search tool failed to search documentation",
            query=query,
            error=str(e),
        )
        return DocumentSearchToolResponse(
            error=f"Failed to search documentation: {e!s}"
        )


# Export the function tools for use in the agent
DOCUMENT_SEARCH_TOOLS = [search_rasa_documentation]
